import { decodeSprite, type Sprite, type SpriteJson } from '@dotoro/kernel';
import galleryJson from '../assets/gallery.json';
import systemJson from '../assets/system.json';

// Generated by `pnpm assets` from assets-src/manifest.json.
const system = systemJson as unknown as Record<string, SpriteJson>;

function systemSprite(name: string): Sprite {
  const json = system[name];
  if (!json) throw new Error(`Missing system sprite "${name}" — run \`pnpm assets\``);
  return decodeSprite(json);
}

export const SPRITES = {
  boot: systemSprite('boot'),
  vfdTemplate: systemSprite('vfdTemplate'),
  vfdHeaders: [
    systemSprite('vfdFocus1'),
    systemSprite('vfdRest1'),
    systemSprite('vfdFocus2'),
    systemSprite('vfdRest2'),
  ],
} as const;

export const GALLERY: readonly Sprite[] = (galleryJson as unknown as SpriteJson[]).map(decodeSprite);
